# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::BillingFence, "with the ownership row missing" do
  # "Every monolith billing write transaction (invoice, line item, invoice tax, payment, mobile-collection
  # payment included) takes FOR SHARE on the `timekeeping_ownership` row and reads `handoff_step` under that lock."
  # A missing row must neither let the write through nor surface as a 404 for the caller's invoice.
  it "refuses with OwnershipMoving rather than RecordNotFound when the ownership row is missing" do
    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).delete_all
    block_ran = false

    expect {
      described_class.transaction { block_ran = true }
    }.to raise_error(Timekeeping::BillingFence::OwnershipMoving)

    expect(block_ran).to be(false)
  end
end

RSpec.describe Timekeeping::BillingFence, "admit outside a transaction", committed_data: true do
  # "Every monolith billing write transaction (invoice, line item, invoice tax, payment, mobile-collection
  # payment included) takes FOR SHARE on the `timekeeping_ownership` row and reads `handoff_step` under that lock."
  # A check outside a transaction releases the lock at once, so a later write could commit after the handoff's update.
  it "refuses an admit check made outside any open transaction" do
    expect(ActiveRecord::Base.connection.transaction_open?).to be(false)

    expect { described_class.admit! }.to raise_error(Timekeeping::BillingFence::TransactionRequired)
  end
end
